mapper.select:
SELECT ,
       COUNT(DISTINCT customer_id) AS customer_count
FROM report_customer_conversion_event
WHERE organization_id = #{orgId}
  AND event_type = #{eventType}
  AND event_time BETWEEN #{startTime} AND #{endTime}

GROUP BY

SELECT DISTINCT signer_id FROM report_customer_conversion_event
WHERE organization_id = #{orgId} AND event_type = #{eventType}
  AND event_time BETWEEN #{startTime} AND #{endTime}
  AND signer_id IS NOT NULL

SELECT event_type, business_id, customer_id, customer_name, customer_mobile,
       signer_id AS employee_id, signer_name AS employee_name,
       signer_dept_id AS department_id, signer_dept_name AS department_name,
       event_time, stat_date
FROM report_customer_conversion_event
WHERE organization_id = #{orgId} AND event_type = #{eventType}
  AND event_time BETWEEN #{startTime} AND #{endTime}


ORDER BY event_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM report_customer_conversion_event
WHERE organization_id = #{orgId} AND event_type = #{eventType}
  AND event_time BETWEEN #{startTime} AND #{endTime}

SELECT COUNT(*) FROM report_employee_stat_event
WHERE organization_id = #{orgId} AND metric_type = 'VISIT_CUSTOMER' AND valid_flag = 1
  AND event_time BETWEEN #{startTime} AND #{endTime}

SELECT COUNT(*) FROM contract
WHERE organization_id = #{orgId} AND effective_version_id IS NOT NULL
  AND start_time BETWEEN #{startTime} AND #{endTime}
